--!strict
local ReplicatedStorage = game:GetService("ReplicatedStorage");
local Players = game:GetService("Players");
local WorldEventService = require(game:GetService("ServerScriptService"):WaitForChild("WorldEventService"));

local Remotes = ReplicatedStorage:WaitForChild("Remotes");
local RequestCollect = Remotes:WaitForChild("RequestCollect") :: RemoteEvent;

local CONFIG = {
	MAX_DISTANCE = 20, -- Slightly larger than client to account for lag
	DEBOUNCE_TIME = 0.4
};

local playerDebounces = {};

local function handleCollection(player: Player, targetPart: BasePart)
	if not targetPart or not targetPart:IsDescendantOf(workspace) then return end

	-- Security check: Verify distance on server
	local character = player.Character;
	if not character or not character:FindFirstChild("HumanoidRootPart") then return end

	local rootPart = character.HumanoidRootPart :: BasePart;
	local distance = (rootPart.Position - targetPart.Position).Magnitude;

	if distance > CONFIG.MAX_DISTANCE then
		warn(player.Name .. " tried to collect from too far away!");
		return;
	end

	-- Check for model attribute
	local parentModel = targetPart:FindFirstAncestorWhichIsA("Model");
	if parentModel and parentModel:GetAttribute("IsCollectable") == true then
		-- Logic: Grant reward
		WorldEventService.AddContribution(player, 1, "Collect");
		print("Server: Successfully collected", targetPart.Name, "for", player.Name);

		-- Destroy or disable target
		targetPart:Destroy();
	end
end

RequestCollect.OnServerEvent:Connect(function(player: Player, targetPart: BasePart)
	local now = os.clock();
	local lastClick = playerDebounces[player.UserId] or 0;

	if (now - lastClick) > CONFIG.DEBOUNCE_TIME then
		playerDebounces[player.UserId] = now;
		handleCollection(player, targetPart);
	end
end);

Players.PlayerRemoving:Connect(function(player: Player)
	playerDebounces[player.UserId] = nil;
end);

--// Auction House Mail
-- Pending rewards for offline sellers/buyers (gems and returned pets).
-- One DataStore key per user ("M_<userId>"), cached in memory while the
-- player is connected.

local Shards = require(script.Parent.Shards)

local Mail = {}

local MailCache = {} -- [userId] = { gems = number, pets = { [petId] = { petName = string } } }

local function GetStore()
	return Shards.GetStore()
end

function Mail.HasCache(UserId)
	return MailCache[UserId] ~= nil
end

function Mail.Get(UserId)
	if MailCache[UserId] then return MailCache[UserId] end

	local Success, Data = pcall(function()
		return GetStore():GetAsync("M_" .. UserId)
	end)

	local Cached = { gems = 0, pets = {} }
	if Success and type(Data) == "table" then
		Cached.gems = Data.gems or 0
		Cached.pets = Data.pets or {}
	end

	MailCache[UserId] = Cached
	return Cached
end

function Mail.Save(UserId)
	local Cached = MailCache[UserId]
	if not Cached then return false end

	local Success, Err = pcall(function()
		GetStore():SetAsync("M_" .. UserId, Cached)
	end)

	if not Success then warn("[AuctionHouse] Failed to save mail for " .. UserId .. ": " .. tostring(Err)) end
	return Success
end

function Mail.Update(UserId, Mutator)
	local Success, Data = pcall(function()
		return GetStore():UpdateAsync("M_" .. UserId, function(Old)
			Old = (type(Old) == "table" and Old) or { gems = 0, pets = {} }
			return Mutator(Old)
		end)
	end)

	if Success then
		MailCache[UserId] = Data
	end
	return Success
end

function Mail.Flush(UserId)
	if MailCache[UserId] then
		Mail.Save(UserId)
		MailCache[UserId] = nil
	end
end

return Mail

