local Remotes = ReplicatedStorage:WaitForChild("Remotes");
local RequestCollect = Remotes:WaitForChild("RequestCollect") :: RemoteEvent;

local CONFIG = {
	MAX_DISTANCE = 20, -- Slightly larger than client to account for lag
	DEBOUNCE_TIME = 0.4
};

local playerDebounces = {};

local function handleCollection(player: Player, targetPart: BasePart)
	if not targetPart or not targetPart:IsDescendantOf(workspace) then return end

	-- Security check: Verify distance on server
	local character = player.Character;
	if not character or not character:FindFirstChild("HumanoidRootPart") then return end

	local rootPart = character.HumanoidRootPart :: BasePart;
	local distance = (rootPart.Position - targetPart.Position).Magnitude;

	if distance > CONFIG.MAX_DISTANCE then
		warn(player.Name .. " tried to collect from too far away!");
		return;
	end

	-- Check for model attribute
	local parentModel = targetPart:FindFirstAncestorWhichIsA("Model");
	if parentModel and parentModel:GetAttribute("IsCollectable") == true then
		-- Logic: Grant reward
		WorldEventService.AddContribution(player, 1, "Collect");
		print("Server: Successfully collected", targetPart.Name, "for", player.Name);

		-- Destroy or disable target
		targetPart:Destroy();
	end
end

RequestCollect.OnServerEvent:Connect(function(player: Player, targetPart: BasePart)
	local now = os.clock();
	local lastClick = playerDebounces[player.UserId] or 0;

	if (now - lastClick) > CONFIG.DEBOUNCE_TIME then
		playerDebounces[player.UserId] = now;
		handleCollection(player, targetPart);
	end
end);

Players.PlayerRemoving:Connect(function(player: Player)
	playerDebounces[player.UserId] = nil;
end);

