--// Admin Dashboard Actions
-- Central dispatcher: routes action strings to the appropriate handler module.
-- Every call is server-authoritative; clients can only request by name + args.

local Actions = {}

-- Handlers (lazy-loaded)
local Handlers = {}

local function GetHandler(Name)
	if not Handlers[Name] then
		Handlers[Name] = require(script.Parent.Handlers[Name])
	end
	return Handlers[Name]
end

function Actions.Handle(Action, ...)
	local Args = { ... }

	--// Players
	if Action == "getPlayers" then
		return GetHandler("Players").ListPlayers()

	elseif Action == "getPlayerData" then
		return GetHandler("Players").GetPlayerData(GetHandler("Players").FindPlayer(Args[1]))

	elseif Action == "setCurrency" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").SetCurrency(P, Args[2])

	elseif Action == "giveCurrency" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").GiveCurrency(P, Args[2])

	elseif Action == "setGems" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").SetGems(P, Args[2])

	elseif Action == "giveGems" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").GiveGems(P, Args[2])

	elseif Action == "setRebirths" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").SetRebirths(P, Args[2])

	elseif Action == "setZone" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").SetZone(P, Args[2])

	elseif Action == "setGemUpgrade" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").SetGemUpgrade(P, Args[2], Args[3])

	elseif Action == "toggleGamepass" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").ToggleGamepass(P, Args[2], Args[3])

	elseif Action == "kick" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Players").KickPlayer(P, Args[2])

	--// Pets
	elseif Action == "getPets" then
		return GetHandler("Pets").AllPets()

	elseif Action == "givePet" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		if not P then return false, "Player not found" end
		return GetHandler("Pets").GrantPet(P, Args[2])

	elseif Action == "deleteAllPets" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Pets").DeleteAllPets(P)

	elseif Action == "deletePet" then
		local P = GetHandler("Players").FindPlayer(Args[1])
		return GetHandler("Pets").DeleteSpecificPet(P, Args[2])

	elseif Action == "setPetSetting" then
		return GetHandler("Pets").SetPetSetting(Args[1], Args[2], Args[3])

	--// Eggs
	elseif Action == "getEggs" then
		return GetHandler("Eggs").AllEggs()

	elseif Action == "setEggCost" then
		return GetHandler("Eggs").SetEggCost(Args[1], Args[2])

	elseif Action == "setEggPetChance" then
		return GetHandler("Eggs").SetPetChance(Args[1], Args[2], Args[3])

	--// Settings
	elseif Action == "getSettings" then
		return GetHandler("Settings").AllGameSettings()

	elseif Action == "setSetting" then
		return GetHandler("Settings").SetSetting(Args[1], Args[2])

	elseif Action == "getAreas" then
		return GetHandler("Settings").AllAreas()

	elseif Action == "setAreaCost" then
		return GetHandler("Settings").SetAreaCost(Args[1], Args[2])

	elseif Action == "getGemShop" then
		return GetHandler("Settings").AllGemShop()

	--// Economy
	elseif Action == "getEconomyStats" then
		return GetHandler("Economy").GetStats()

	elseif Action == "giveAllCurrency" then
		return GetHandler("Economy").GiveAllCurrency(Args[1])

	elseif Action == "giveAllGems" then
		return GetHandler("Economy").GiveAllGems(Args[1])

	--// Auction
	elseif Action == "clearListings" then
		return GetHandler("Auction").ClearAllListings()

	--// Codes
	elseif Action == "getCodes" then
		return GetHandler("Codes").ListCodes()

	--// Server
	elseif Action == "getServerInfo" then
		return GetHandler("Server").GetInfo()

	elseif Action == "getServerStats" then
		return GetHandler("Server").GetServerStats()

	elseif Action == "shutdown" then
		return GetHandler("Server").Shutdown()

	--// Logs
	elseif Action == "getLogs" then
		return require(script.Parent.Logs).Get(Args[1] or 100)

	elseif Action == "clearLogs" then
		return require(script.Parent.Logs).Clear()
	end

	return nil, "Unknown action: " .. tostring(Action)
end

return Actions

