local function handleCollection(player: Player, targetPart: BasePart)
	if not targetPart or not targetPart:IsDescendantOf(workspace) then return end

	-- Security check: Verify distance on server
	local character = player.Character;
	if not character or not character:FindFirstChild("HumanoidRootPart") then return end

	local rootPart = character.HumanoidRootPart :: BasePart;
	local distance = (rootPart.Position - targetPart.Position).Magnitude;

	if distance > CONFIG.MAX_DISTANCE then
		warn(player.Name .. " tried to collect from too far away!");
