local UserInputService = game:GetService("UserInputService");
local ReplicatedStorage = game:GetService("ReplicatedStorage");
local Players = game:GetService("Players");
local Workspace = game:GetService("Workspace");

local CONFIG = {
	MAX_DISTANCE = 15,
	INTERACTION_TAG = "Collectable",
	COOLDOWN = 0.5
};

-- Ensure Remotes folder exists
local Remotes = ReplicatedStorage:FindFirstChild("Remotes") or Instance.new("Folder", ReplicatedStorage);
Remotes.Name = "Remotes";

local RequestCollect = Remotes:FindFirstChild("RequestCollect") :: RemoteEvent;
if not RequestCollect then
	RequestCollect = Instance.new("RemoteEvent");
	RequestCollect.Name = "RequestCollect";
	RequestCollect.Parent = Remotes;
end

local localPlayer = Players.LocalPlayer;
local mouse = localPlayer:GetMouse();
local lastClickTime = 0;

local function getTargetPart(): BasePart?
	local camera = Workspace.CurrentCamera;
	if not camera then return nil end

	local rayOrigin = camera.CFrame.Position;
	local rayDirection = mouse.UnitRay.Direction * CONFIG.MAX_DISTANCE;

	local raycastParams = RaycastParams.new();
	raycastParams.FilterType = Enum.RaycastFilterType.Exclude;
	raycastParams.FilterDescendantsInstances = {localPlayer.Character or {}};

	local raycastResult = Workspace:Raycast(rayOrigin, rayDirection, raycastParams);
	if raycastResult and raycastResult.Instance then
		local parentModel = raycastResult.Instance:FindFirstAncestorWhichIsA("Model");
		if parentModel and parentModel:GetAttribute("IsCollectable") == true then
			return raycastResult.Instance;
		end
	end
	return nil;
end

local function onInputBegan(input: InputObject, gameProcessed: boolean)
	if gameProcessed then return end
	if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end

	local now = os.clock();
	if (now - lastClickTime) < CONFIG.COOLDOWN then return end

	local target = getTargetPart();
	if target then
		lastClickTime = now;
		local success, err = pcall(function()
			RequestCollect:FireServer(target);
			print("⚡ Interaction request sent for:", target:GetFullName());
		end);

		if not success then
			warn("Failed to fire RequestCollect:", err);
		end
	end
end

-- Initialize Connections
local connection = UserInputService.InputBegan:Connect(onInputBegan);

-- Memory Cleanup
local function onAncestryChanged()
	if not localPlayer.Parent then
		connection:Disconnect();
	end
end

localPlayer.AncestryChanged:Connect(onAncestryChanged);

print("✅ InteractionManager initialized successfully.");

