	return Shards.GetStore()
end

function Mail.HasCache(UserId)
	return MailCache[UserId] ~= nil
end

function Mail.Get(UserId)
	if MailCache[UserId] then return MailCache[UserId] end

	local Success, Data = pcall(function()
		return GetStore():GetAsync("M_" .. UserId)
	end)

	local Cached = { gems = 0, pets = {} }
	if Success and type(Data) == "table" then
		Cached.gems = Data.gems or 0
		Cached.pets = Data.pets or {}
	end

	MailCache[UserId] = Cached
	return Cached
end

function Mail.Save(UserId)
	local Cached = MailCache[UserId]
	if not Cached then return false end

	local Success, Err = pcall(function()
		GetStore():SetAsync("M_" .. UserId, Cached)
	end)

	if not Success then warn("[AuctionHouse] Failed to save mail for " .. UserId .. ": " .. tostring(Err)) end
	return Success
end

function Mail.Update(UserId, Mutator)
	local Success, Data = pcall(function()
		return GetStore():UpdateAsync("M_" .. UserId, function(Old)
			Old = (type(Old) == "table" and Old) or { gems = 0, pets = {} }
			return Mutator(Old)
		end)
	end)

	if Success then
		MailCache[UserId] = Data
	end
	return Success
end

function Mail.Flush(UserId)
	if MailCache[UserId] then
		Mail.Save(UserId)
		MailCache[UserId] = nil
	end
end

